const crypto = require('node:crypto');
const Module = require('node:module');
const zlib = require('node:zlib');

const EXPECTED_BRIDGE_SHA256 = '8af9f491dc8532ef2e6e43f5d040f0c4c5a4ff634ecc37a3d0f2f3ddcd93de96';
const BUNDLED_BRIDGE_GZIP_BASE64 = '';
let handler = null;

function loadHandler() {
  if (handler) return handler;
  const sourceBytes = zlib.gunzipSync(Buffer.from(BUNDLED_BRIDGE_GZIP_BASE64, 'base64'));
  const actualHash = crypto.createHash('sha256').update(sourceBytes).digest('hex');
  if (actualHash !== EXPECTED_BRIDGE_SHA256) {
    throw new Error('bundled bridge integrity check failed');
  }
  const compiled = new Module('glaciereq-v21-bundled-bridge.js', module);
  compiled.filename = 'glaciereq-v21-bundled-bridge.js';
  compiled.paths = module.paths;
  compiled._compile(sourceBytes.toString('utf8'), compiled.filename);
  if (typeof compiled.exports !== 'function') {
    throw new Error('bundled bridge export is not a handler');
  }
  handler = compiled.exports;
  return handler;
}

module.exports = async function bootstrap(req, res) {
  try {
    return await loadHandler()(req, res);
  } catch (error) {
    console.error('Bundled bridge bootstrap failure', error);
    res.statusCode = 502;
    res.setHeader('Content-Type', 'text/plain; charset=utf-8');
    res.setHeader('Cache-Control', 'no-store');
    res.setHeader('Retry-After', '60');
    res.end('Bundled bridge bootstrap unavailable');
  }
};
